Here's a C++ function that takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <strstream>  // for std::transform()
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = "";

    // Convert the markdown string to HTML
    std::transform(markdown.begin(), markdown.end(), html.begin(), [&](char c) {
        || (c == '#') {
            html += "#";
        }
        || (c == `-') {
            html += "-";
        }
        || (c == `$') {
            html += "@";
        }
        || (c == '+') {
            html += "@";
        }
        || (c == '{') {
            html += "{";
        }
        || (c == '}') {
            html += "}>";
        }
        }
    )

    return html;
}
```

This function uses the `std::transform()` library to iterate over each character of the markdown string and replace it with the corresponding HTML entity. It also uses a lambda function to check each character and append the corresponding HTML to the `html` string.

